using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using StArray.ModManager.Manager;
using StArray.ModManager.RuntimeAbstractions;

namespace FirstPersonCamera.Port.Runtime;

/// <summary>
/// Locates a game/engine class by <c>namespace.name</c> across whatever images the running build
/// actually contains, instead of assuming a specific assembly file name.
///
/// <para>
/// This matters because the desktop mod's assembly names are an artefact of MelonLoader: it generated
/// <c>Il2CppCinemachine.dll</c>, <c>Il2CppHLAutoGenerated.dll</c> … from the game's metadata. On the
/// device those images do not exist. A game typically ships one <c>Assembly-CSharp.dll</c> holding all
/// gameplay code (Cinemachine is frequently compiled <i>into</i> it as source), while Unity's own types
/// sit in <c>UnityEngine.*.dll</c>. Pinning our lookups to the desktop names therefore guarantees a
/// miss on Android.
/// </para>
///
/// <para>
/// Resolution order, cheapest first:
/// </para>
/// <list type="number">
/// <item>the image that actually <i>defines</i> the class, when the runtime can tell us
/// (<c>il2cpp_class_get_image</c> + <c>il2cpp_image_get_name</c> on a successful lookup);</item>
/// <item>a short, ordered candidate list for the namespace (so the common case costs one or two
/// probes);</item>
/// <item>a linear scan over every loaded image — the fallback that makes the mod work on a build
/// whose image layout we have never seen.</item>
/// </list>
///
/// Every attempt is logged once per class, and a miss is cached only for a bounded period so a class
/// that appears later (scene-streamed content) can still be picked up.
/// </summary>
internal static class ClassIndex
{
    private sealed class Entry
    {
        internal nint Klass;
        internal string Image;
        internal int Failures;
        internal double RetryAfter;
    }

    private static readonly Dictionary<string, Entry> Cache = new(StringComparer.Ordinal);
    private static readonly object Lock = new();

    /// <summary>Re-probe a missing class at most once every 10 s.</summary>
    private const double RetryIntervalSeconds = 10.0;

    /// <summary>Images probed first for a given namespace, before the full scan.</summary>
    private static string[] PreferredImages(string ns)
    {
        switch (ns)
        {
            case "UnityEngine":
            case "UnityEngine.SceneManagement":
                return new[] { "UnityEngine.CoreModule.dll", "UnityEngine.dll" };

            case "Cinemachine":
                return new[]
                {
                    "Assembly-CSharp.dll",      // Cinemachine compiled as source (common)
                    "Cinemachine.dll",
                    "Unity.Cinemachine.dll",
                };

            case "Hardlight":
                return new[]
                {
                    "Assembly-CSharp.dll",
                    "HLRuntime.dll",
                    "Hardlight.dll",
                };

            default:
                return new[] { "Assembly-CSharp.dll" };
        }
    }

    /// <summary>Class pointer for <paramref name="ns"/>.<paramref name="name"/>, or 0.</summary>
    internal static nint Find(string ns, string name)
    {
        var key = ns + "." + name;

        lock (Lock)
        {
            if (Cache.TryGetValue(key, out var hit))
            {
                if (hit.Klass != 0) return hit.Klass;
                if (Environment.TickCount64 / 1000.0 < hit.RetryAfter) return 0;
            }
        }

        var klass = Resolve(ns, name, out var image);

        lock (Lock)
        {
            if (!Cache.TryGetValue(key, out var entry))
            {
                entry = new Entry();
                Cache[key] = entry;
            }

            if (klass != 0)
            {
                if (entry.Klass == 0)
                    Logger.Info("ClassIndex", $"{key} → {image ?? "<unknown image>"}");
                entry.Klass = klass;
                entry.Image = image;
                entry.Failures = 0;
            }
            else
            {
                entry.Failures++;
                entry.RetryAfter = Environment.TickCount64 / 1000.0 + RetryIntervalSeconds;

                // Warn on the first miss only; the retry timer keeps the log clean afterwards.
                if (entry.Failures == 1)
                    Logger.Warn("ClassIndex", $"{key} not found in any loaded image (will retry).");
            }
        }

        return klass;
    }

    private static nint Resolve(string ns, string name, out string image)
    {
        image = null;

        var domain = RuntimeManager.GetDomain();
        if (domain == null) return 0;

        // ── 1. preferred images ──
        foreach (var candidate in PreferredImages(ns))
        {
            var klass = TryImage(domain, candidate, ns, name);
            if (klass != 0) { image = candidate; return klass; }
        }

        // ── 2. every loaded image ──
        try
        {
            foreach (var asm in domain.GetAssemblies())
            {
                try
                {
                    var klass = asm.GetClass(ns, name);
                    if (klass == null || klass.Ptr == 0) continue;

                    image = asm.Name;
                    return klass.Ptr;
                }
                catch
                {
                    // One unreadable image must not abort the scan.
                }
            }
        }
        catch (Exception ex)
        {
            Logger.Warn("ClassIndex", $"image scan failed: {ex.Message}");
        }

        return 0;
    }

    private static nint TryImage(IAppDomain domain, string imageName, string ns, string name)
    {
        try
        {
            var asm = domain.OpenAssembly(imageName);
            var klass = asm?.GetClass(ns, name);
            return klass?.Ptr ?? 0;
        }
        catch
        {
            return 0;
        }
    }

    /// <summary>True when the image is present in this build (used by the startup self-test).</summary>
    internal static bool HasImage(string imageName)
    {
        try { return RuntimeManager.GetDomain()?.OpenAssembly(imageName) != null; }
        catch { return false; }
    }

    /// <summary>Names of every image currently loaded — the raw material for diagnosing a miss.</summary>
    internal static IReadOnlyList<string> LoadedImages()
    {
        var list = new List<string>();
        try
        {
            var domain = RuntimeManager.GetDomain();
            if (domain == null) return list;

            foreach (var asm in domain.GetAssemblies())
            {
                try
                {
                    var name = asm.Name;
                    if (!string.IsNullOrEmpty(name)) list.Add(name);
                }
                catch { }
            }
        }
        catch { }

        return list;
    }

    private delegate nint ClassGetImageFn(nint klass);
    private delegate nint ImageGetNameFn(nint image);

    /// <summary>
    /// Name of the image that defines a class pointer (diagnostics).
    /// Both exports are internal to StArray, so they are bound through <see cref="StArrayBridge"/>.
    /// </summary>
    internal static string ImageOf(nint klass)
    {
        if (klass == 0) return null;

        try
        {
            var functions = StArrayBridge.FindType("StArray.ModManager.Il2Cpp.Il2CppFunctions");
            var getImage = StArrayBridge.Delegate<ClassGetImageFn>("il2cpp_class_get_image",
                functions, "il2cpp_class_get_image", 1);
            var getName = StArrayBridge.Delegate<ImageGetNameFn>("il2cpp_image_get_name",
                functions, "il2cpp_image_get_name", 1);

            if (getImage == null || getName == null) return null;

            var image = getImage(klass);
            if (image == 0) return null;

            var namePtr = getName(image);
            return namePtr == 0 ? null : Marshal.PtrToStringAnsi(namePtr);
        }
        catch { return null; }
    }

    internal static void Clear()
    {
        lock (Lock) Cache.Clear();
    }
}
